import {BrowserRouter as Router,Route,Routes} from'react-router-dom'
import Login from './Login';
import Reg from './Reg';
import Producet from './Producet';
import Admindeshboard from './Admindeshboard';
import Header from './Header';
import Footer from './Footer';
import { Contextapi } from './Contextapi';
import { useState } from 'react';

function App() {
 const[loginname,setloginname] =useState.Contextapi(localStorage.getItem('loginname'))
  return (  
<Router>
  <Contextapi.Provider value={{loginname}}>
      <Header/>
      <Routes>
        <Route path='/' element={<Login/>}></Route>
        <Route path='/Reg' element={<Reg/>}></Route>
        <Route path='/product' element={<Producet/>}></Route>
        <Route path='/deshboard' element={<Admindeshboard/>}></Route>
      </Routes>
<Footer/>
</Contextapi.Provider>
    </Router>

  );
}

export default App;
